package za.ac.cput.hospital.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import za.ac.cput.hospital.dao.UserDao;import java.io.IOException;
@WebServlet("/users") public class UserServlet extends HttpServlet{private final UserDao dao=new UserDao();protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{try{q.setAttribute("users",dao.search(q.getParameter("search")));q.getRequestDispatcher("/WEB-INF/views/users.jsp").forward(q,s);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException,ServletException{try{dao.setActive(Integer.parseInt(q.getParameter("id")),Boolean.parseBoolean(q.getParameter("active")));q.getSession().setAttribute("flash","User status updated.");s.sendRedirect(q.getContextPath()+"/users");}catch(Exception e){throw new ServletException(e);}}}
